float st=.025, maxdist=15.;
vec3 ldir=vec3(0.,-1.,-1.),col=vec3(0.);

mat2 rot(float a) {
	float s=sin(a),c=cos(a);
    return mat2(c,s,-s,c);
}
#define R(p,a,r)mix(a*dot(p,a),p,cos(r))+sin(r)*cross(p,a)
#define H(h)(cos((h)*6.3+vec3(0,23,21))*.5+.5)
#define PI 3.14
void pModPolar(inout vec2 p, float repetitions) 
{
	float angle = PI / repetitions;
	float a2 = 2.0 * angle;
	float a = atan(p.y, p.x) + angle;
	float r = length(p);
	float c = floor(a / a2);
	a = mod(a,a2) - angle;
	p = r * vec2(cos(a), sin(a));
}

vec3 fractal(vec2 p) {
    vec2 pos=p;

    float d, ml=100.;
    vec2 mc=vec2(100.);
    p=abs(fract(p*.21)-.5);
    vec2 c=p;
    for(int i=0;i<10;i++) {
        d=dot(p+0.2*sin(iTime),p+0.2*cos(iTime));
        p=abs(p+1.)-abs(p-1.)-p;

    	p=p*-1.05/clamp(d,0.25,1.)-c;
        mc=min(mc,abs(p));
        if (i>2) ml=min(ml*(1.+float(i)*.1),abs(p.y-.5));
    }
    mc=max(vec2(0.),1.-mc);
    mc=normalize(mc)*.8;
    ml=pow(max(0.,1.-ml),6.);
    return vec3(mc,d*.4)*ml*(step(0.17,fract(d*.1+iTime*.5+pos.x*.2)))-ml*.1;
}

float map(vec2 p) {
    vec2 pos=p;

    float t=iTime*1.1;
    col+=fractal(p);
    vec2 p2=abs(.5-fract(p*8.+4.));
	float h=0.;


    vec2 p3=p;

    p=floor(p*2.+1.);
       p.xy*=rot(-iTime*0.01);
    float l=length(p2*p2);

     vec2 cPos = -1.0 + 2.0 * p.xy / iResolution.xy;

    // distance of current pixel from center
	float cLength = length(cPos);

 p=floor(p*2.+1.);
      p.xy*=rot(-iTime*1.01);

    h+=max(0.,2.-length(p-vec2(18.,0.)))*1.5;
    h+=max(0.,5.-length(p+vec2(18.,10.)))*1.5;
	 p.xy*=rot(-iTime*0.01);
    p=p*2.+.2345;
    t*=.5;

    return h;
}

vec3 normal(vec2 p, float td) {
	vec2 eps=vec2(0.,.001);
    return normalize(vec3(map(p+eps.yx)-map(p-eps.yx),2.*eps.y,map(p+eps.xy)-map(p-eps.xy)));
}

vec2 hit(vec3 p) {
    float h=map(p.xz);
    return vec2(step(p.y,h),h);
}

vec3 bsearch(vec3 from,vec3 dir,float td) {
    vec3 p;

      p*=2.5+asin(2.9*sin(iTime*.2))*.3;
    st*=-2.5;
    td+=st;
    float h2=1.;
    for (int i=0;i<20;i++) {
        p=from+td*dir;

        float h=hit(p).x;
        if (abs(h-h2)>.001) {
            st*=-.5;
	        h2=h;
        }
        td+=st;
    }
	return p;
}

vec3 shade(vec3 p,vec3 dir,float h,float td) {
    ldir=normalize(ldir);

	col=vec3(0.);
    vec3 n=normal(p.xz,td);
	col*=0.325;
    float dif=max(0.,dot(ldir,-n));
    vec3 ref=reflect(ldir,dir);
    float spe=pow(max(0.,dot(ref,-n)),8.);
    return col+(dif*.5+.2+spe*vec3(1.,.8,.5))*.2;
}


vec3 march(vec3 from,vec3 dir) {
	vec3 p, col=vec3(0.);

    float td=.5, k=0.;
    vec2 h;
    for (int i=0;i<600;i++) {
    	p=from+dir*td;
        h=hit(p);
        if (h.x>.5||td>maxdist) break;
        td+=st;
    }
    if (h.x>.5) {
        p=bsearch(from,dir,td);
    	col=shade(p,dir,h.y,td);
    } else {
    }
	col=mix(col,2.*vec3(mod(gl_FragCoord.y,4.)*.1),pow(td/maxdist,3.));
    return col*vec3(.9,.8,1.);
}
#define rot(a) mat2(cos(a), sin(a), -sin(a), cos(a))
mat3 lookat(vec3 dir,vec3 up) {
	dir=normalize(dir);vec3 rt=normalize(cross(dir,normalize(up)));
    return mat3(rt,cross(rt,dir),dir);
}

vec3 path(float t) {
	return vec3((t)*0.5,1.,sin(t*0.))*3.5;
}

void mainImage(out vec4 fragColor,in vec2 fragCoord)
{
    vec2 uv = (fragCoord-iResolution.xy*.5)/iResolution.y;
    uv*=rot(-iTime);
	float t=iTime*1.2;
    vec3 from=path(t);
       pModPolar(uv, 3.);
    vec3 dir=normalize(vec3(uv,1.5));
  dir.xy*=rot(-iTime);
    vec3 adv=path(t+.1)-from;
     adv.zy*=rot(-iTime*1.01);
    dir=lookat(adv+vec3(2.,-.2-(1.+sin(t*0.)),0.),vec3(adv.y*.1,1.,0.))*dir;
    vec3 col=march(from, dir)*1.5;
    fragColor = vec4(col,1.);
}
